import { useState, useEffect } from "react";

function Marks() {
  const [students, setStudents] = useState([]);
  const [selectedStudent, setSelectedStudent] = useState("");
  const [subjectName, setSubjectName] = useState("");
  const [totalMarks, setTotalMarks] = useState("");
  const [marksObtained, setMarksObtained] = useState("");
  const [marksData, setMarksData] = useState({}); // { studentId: { subject: { total, obtained } } }

  useEffect(() => {
    const allStudents = JSON.parse(localStorage.getItem("students")) || [];
    setStudents(allStudents);

    const savedMarks = JSON.parse(localStorage.getItem("marks")) || {};
    setMarksData(savedMarks);
  }, []);

  const handleAddMarks = () => {
    if (!selectedStudent || !subjectName || !totalMarks || !marksObtained) return;

    const studentMarks = marksData[selectedStudent] || {};
    studentMarks[subjectName] = { total: Number(totalMarks), obtained: Number(marksObtained) };

    const updatedMarks = { ...marksData, [selectedStudent]: studentMarks };
    setMarksData(updatedMarks);
    localStorage.setItem("marks", JSON.stringify(updatedMarks));

    // Clear inputs
    setSubjectName("");
    setTotalMarks("");
    setMarksObtained("");
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Marks Entry</h2>

      {/* Student Selection Dropdown */}
      <div style={{ marginBottom: "15px" }}>
        <label>Select Student: </label>
        <select value={selectedStudent} onChange={e => setSelectedStudent(e.target.value)}>
          <option value="">--Select Student--</option>
          {students.map(s => (
            <option key={s.id} value={s.id}>{s.name}</option>
          ))}
        </select>
      </div>

      {/* Marks Entry Form */}
      {selectedStudent && (
        <div style={{ marginBottom: "20px" }}>
          <input
            placeholder="Subject Name"
            value={subjectName}
            onChange={e => setSubjectName(e.target.value)}
          />
          <input
            type="number"
            placeholder="Total Marks"
            value={totalMarks}
            onChange={e => setTotalMarks(e.target.value)}
          />
          <input
            type="number"
            placeholder="Marks Obtained"
            value={marksObtained}
            onChange={e => setMarksObtained(e.target.value)}
          />
          <button onClick={handleAddMarks} style={{ marginLeft: "5px" }}>Add Marks</button>
        </div>
      )}

      {/* Show all students with marks summary */}
      <h3>Students List</h3>
      <table border="1" cellPadding="8" style={{ borderCollapse: "collapse", width: "100%" }}>
        <thead>
          <tr style={{ background: "#f0f0f0" }}>
            <th>Name</th>
            <th>Roll</th>
            <th>Subjects Added</th>
          </tr>
        </thead>
        <tbody>
          {students.map(student => {
            const studentMarks = marksData[student.id] || {};
            const subjects = Object.keys(studentMarks);
            return (
              <tr key={student.id}>
                <td>{student.name}</td>
                <td>{student.roll}</td>
                <td>{subjects.length > 0 ? subjects.join(", ") : "-"}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
export default Marks;
